public class METCrossDockSalesOrderAutoExtractService extends METSysOperationService
{
    private METCrossDockSalesOrderAutoExtractTaskContract contract;
    private guid queueId;
    Query userQuery;
}

Method.Source:
// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METCrossDockSalesOrderAutoExtractTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METCrossDockSalesOrderAutoExtractTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:xDockSalesAutoExtractionBatchTitle";
}

/// <summary>
/// constructs the field maps used to insert data from user query to temporary staging table.
/// </summary>
/// <param name = "_dataSourceId">Unique data source of the query data source</param>
/// <returns>Field map</returns>
private Map getFieldMap(int _dataSourceId)
{
    Map fieldsMap = new Map(Types::String, Types::Container);

    fieldsMap.insert(fieldStr(METInternalTransferOrderQueueTmp, SalesId), [_dataSourceId, fieldStr(SalesTable, SalesId)]);

    return fieldsMap;
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METReserveEventOrdersContract</c>
/// </param>
public void process(METCrossDockSalesOrderAutoExtractContract _contract)
{
    userQuery = new Query(_contract.parmPackedQuery());
    this.initialise();
    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables and initiates data staging.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Initializes process and stages data into table <t>METInternalTransferOrderQueue</t>.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    contract            = dataContract as METCrossDockSalesOrderAutoExtractTaskContract;
    queueId = newGuid();

    try
    {
        ttsbegin;

        METInternalTransferOrderQueue::cleanUpQueue();
        this.stageQueue();

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        curext(); 
    }
}

/// <summary>
/// Stages orders to be processed based on user selection and .
/// </summary>
private void stageQueue()
{
    METInternalTransferOrderQueueTmp metInternalTransferQueueTmp;
    METInternalTransferOrderQueue processQueue;
    SalesTable salesTable;
    METSalesTable metSalesTable;

    QueryBuildDataSource qbdsSalesTable = userQuery.dataSourceName(tableStr(SalesTable));
    Query::insert_recordset(metInternalTransferQueueTmp, this.getFieldMap(qbdsSalesTable.uniqueId()), userQuery);

    //Transfer the data from tmp table to Process queue with process Id. 
    insert_recordset processQueue(ProcessId, SalesId)
        select queueId, SalesId from metInternalTransferQueueTmp
        group by metInternalTransferQueueTmp.SalesId;

    // Since the data in processing queue is populated based on user query, 
    // we need to make sure that orders that match below conditions are exculded
    // 1. Orders that are already extracted 
    // 2. Orders that has future release dates (Release date > today()).
    // 3. Event orders (Event Id != '')
    delete_from processQueue
        where processQueue.ProcessId == queueId
        exists join salesTable
        where salesTable.SalesId == processQueue.SalesId
        && salesTable.METOrderExtractStatus == METOrderExtractStatus::Extracted
        exists join metSalesTable
        where metSalesTable.SalesTable == salesTable.RecId
        && metSalesTable.EventID != ''
        && metSalesTable.ReleaseDate > DateTimeUtil::getToday(DateTimeUtil::getCompanyTimeZone());

    //Update the order extraction status to Ready For Extraction so the extraction process will pick this up.
    update_recordset salesTable
        setting METOrderExtractStatus = METOrderExtractStatus::ReadyForExtract
        where processQueue.ProcessId == queueId
        exists join processQueue
        where processQueue.SalesId == salesTable.SalesId
        && salesTable.METOrderExtractStatus == METOrderExtractStatus::Open;
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    contract = _taskDataContract as METCrossDockSalesOrderAutoExtractTaskContract;
    contract.parmTopPickingProcessId(queueId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METCrossDockSalesOrderAutoExtractTaskContract();
}
